-- Migration: Seed global master exercise catalog (876 exercises) into public.exercises
-- Ensures every athlete, coach, and admin has direct database records for all catalog movements.

-- Drop existing overlapping policy if it exists to keep idempotency
DROP POLICY IF EXISTS "Global catalog exercises are viewable by all" ON public.exercises;

CREATE POLICY "Global catalog exercises are viewable by all" ON public.exercises
  FOR SELECT
  TO anon, authenticated
  USING (is_custom = false OR user_id = '00000000-0000-0000-0000-000000000000');

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  type = EXCLUDED.type,
  target_sets = EXCLUDED.target_sets,
  target_rep_min = EXCLUDED.target_rep_min,
  target_rep_max = EXCLUDED.target_rep_max,
  is_custom = false;
